nta.declaration:
// ============================================================
// VERA - Modelo UPPAAL (Entregable 4: Model Checking)
//
// Correspondencia con la especificacion VDM++:
//   SistemaEvacuacion  -> plantilla Sistema
//   Planificador.carga -> variables carga_esc / carga_sal
//   Tipos.capacidad    -> constantes CAP_ESC / CAP_SAL
//   EstadoAula         -> localizaciones de la plantilla Aula
//
// Las capacidades se reducen respecto a la Norma A.130 para
// mantener el model checking tratable, preservando la relacion
// de contension critica: dos aulas de piso 1 compiten por una
// unica escalera cuya capacidad no admite su paso simultaneo
// (2 * 80 = 160 > 150). Cualquier pabellon real se obtiene
// escalando estas constantes.
// ============================================================

const int N_AULAS = 2;      // aulas de piso 1 (cuello de botella escalera)
const int OCUP    = 80;     // personas por aula
const int CAP_ESC = 150;    // escalera 1.20 m  -> floor(1.20/0.008) = 150 (A.130)
const int CAP_SAL = 200;    // salida   1.00 m  -> floor(1.00/0.005) = 200 (A.130)

int carga_esc = 0;          // carga actual de la escalera (Planificador.carga)
int carga_sal = 0;          // carga actual de la salida
int evacuadas = 0;          // numero de aulas en estado EVACUADA
int sin_ruta  = 0;          // numero de aulas en estado SIN_RUTA

bool evacuando     = false; // SistemaEvacuacion.estado = EVACUANDO
bool esc_bloqueada = false; // Tramo escalera.estado    = BLOQUEADO

broadcast chan alerta;      // senal sismica -> activarAlerta()

nta.system:
sistema = Sistema();
entorno = Entorno();
A1 = Aula(1);
A2 = Aula(2);

system sistema, entorno, A1, A2;
